{
  "description": "The creature is shown in right-facing side profile against a plain light beige background. It has the overall size, posture, fur, head shape and paws of a brown bear, but most of its dorsal and lateral surfaces and the outer sides of its limbs are covered in a glossy, dark reddish-brown to black segmented exoskeleton resembling that of a beetle. A single long, slender, black, backward-curving horn with a ridged base rises from the top of the head. The visible fur is thick, shaggy and medium brown on the head, neck, chest, underparts and around the armor edges, with a lighter tan muzzle and darker brown lower limbs. The armor is highly reflective, divided into large overlapping plates along the back and smaller plates on the shoulders, hips and shins, with pale tan ribbed or segmented skin visible on the belly and inner legs. All four paws with claws are on the ground and a small furry tail is visible at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, lighter brown muzzle, black nose at the tip, small dark brown eyes on the sides, and a slightly open mouth",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "one long, thin, glossy black horn that curves strongly backward then forward to a sharp point, with transverse ridges and segmented rings near the base",
      "where": "arising from the midline on top of the head between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on the top sides of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy legs with brown shaggy fur on the inner and upper parts and glossy dark plates on the outer thigh, shoulder and shin, with pale tan ribbed undersides and visible joints",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad bear paws with brown fur on top and dark curved claws on the toes, with small dark platelets on the upper surface of the hind feet",
      "where": "at the bottom tip of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, small, furry brown tuft",
      "where": "at the extreme rear left, protruding from under the rear armor plates"
    },
    {
      "part": "plates",
      "looks_like": "large, smooth, highly glossy dark brown to black chitinous plates with visible sutures, ridges and dotted texture, forming overlapping segments over the back and smaller shield-like plates over the shoulders, hips and lower legs, with a row of oval holes along the lower side and pale tan segmented membranes between",
      "where": "covering the entire back from neck to rump, the sides, and the outer surfaces of all four limbs"
    },
    {
      "part": "shell",
      "looks_like": "a continuous dorsal carapace made of five large overlapping glossy plates along the spine plus smaller plates over the neck and rump, dark and reflective",
      "where": "along the top of the back from just behind the neck to the tail"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle",
    "goat"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
